-- Logotipo do cliente por projeto (PNG, JPEG, WebP ou SVG ate 256 KB), mostrado em vez das
-- iniciais. logo_version muda a cada alteracao para invalidar a cache do browser. Idempotente.
ALTER TABLE projects
  ADD COLUMN IF NOT EXISTS logo_mime VARCHAR(40) CHARACTER SET ascii NULL,
  ADD COLUMN IF NOT EXISTS logo_data MEDIUMBLOB NULL,
  ADD COLUMN IF NOT EXISTS logo_version INT NOT NULL DEFAULT 0;

-- Logotipo real da Pizza Hut (temas/pizzahut/images/logo-small.svg) no projeto inicial, so se
-- ainda nao tiver logotipo; depois gere-se em Projetos > Editar.
UPDATE projects
  SET logo_mime = 'image/svg+xml', logo_data = X'', logo_version = logo_version + 1
  WHERE id = '00000000-0000-4000-8000-000000000001' AND logo_mime IS NULL;
